#!/usr/bin/env python3
"""Build tests/fixtures/dbserver/export/ (a tiny rekordbox export tree) from committed libcdj fixtures.

Copies the libcdj fixture export.pdb and the real ANLZ pairs whose tracks are in that pdb, at the paths the pdb
references (PIONEER/USBANLZ/Pxxx/id/ANLZ0000.DAT|EXT), plus two placeholder artwork files (not real images: the
server just forwards the bytes). Run again after the libcdj fixtures change; never edit the output by hand.
"""
import os
import shutil
import sys

libcdj = os.environ.get('LIBCDJ', os.path.join(os.path.dirname(os.path.abspath(__file__)), '../../../references/libcdj'))
fix = os.path.join(libcdj, 'src/test/fixtures')
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'export')

# fixture file prefix -> pdb track id and what the track is good for
anlz = {
    'P014_00001A7A': 34,     # two hot cues (non loop), DAT PCOB non empty
    'P024_00023562': 2096,   # two loops
    'P02A_0000ECBE': 1372,   # not analysed: empty beat grid, no cues
    'P035_0002765B': 516,    # PCP2 entry with colour bytes
    'P042_00015D16': 1935,   # anchor: 716 beats, 123.00 BPM, one hot-cue loop
    'P04B_000145BD': 1586,   # PVB2 tag, not analysed
    'P07D_0001A2E9': 1932,   # four cues, longest beat grid
}
artwork = {
    '/PIONEER/Artwork/00002/a34.jpg': b'FAKE-ARTWORK-34\n',
    '/PIONEER/Artwork/00026/a511.jpg': b'FAKE-ARTWORK-511\n',
}

shutil.rmtree(out, ignore_errors=True)
os.makedirs(os.path.join(out, 'PIONEER/rekordbox'))
shutil.copy(os.path.join(fix, 'export.pdb'), os.path.join(out, 'PIONEER/rekordbox/export.pdb'))
for prefix in anlz:
    p, i = prefix.split('_')
    d = os.path.join(out, 'PIONEER/USBANLZ', p, i)
    os.makedirs(d)
    for ext in ('DAT', 'EXT'):
        shutil.copy(os.path.join(fix, 'anlz', '%s_ANLZ0000.%s' % (prefix, ext)), os.path.join(d, 'ANLZ0000.' + ext))
for path, data in artwork.items():
    full = os.path.join(out, path.lstrip('/'))
    os.makedirs(os.path.dirname(full), exist_ok=True)
    open(full, 'wb').write(data)

# second export: the 7 track LMMS pendrive (references/libcdj/rekordbox) that the captured deck served; no audio
src7 = os.path.join(libcdj, 'rekordbox')
out7 = os.path.join(os.path.dirname(out), 'export7')
shutil.rmtree(out7, ignore_errors=True)
os.makedirs(os.path.join(out7, 'PIONEER/rekordbox'))
shutil.copy(os.path.join(src7, 'PIONEER/rekordbox/export.pdb'), os.path.join(out7, 'PIONEER/rekordbox/export.pdb'))
shutil.copytree(os.path.join(src7, 'PIONEER/USBANLZ'), os.path.join(out7, 'PIONEER/USBANLZ'), ignore=shutil.ignore_patterns('USBMNG.DAT'))

with open(os.path.join(out, 'MANIFEST.text'), 'w') as f:
    f.write('Fixture rekordbox export for the dbserver tests. Generated by ../build_fixture_export.py from the libcdj fixtures.\n')
    f.write('pdb track id -> analysis files (real rekordbox ANLZ copies):\n')
    for prefix, tid in anlz.items():
        f.write('  %5d  %s\n' % (tid, prefix))
    f.write('artwork placeholders: ' + ', '.join(artwork) + '\n')
open(os.path.join(out7, 'MANIFEST.text'), 'w').write('export.pdb and ANLZ files of the 7 track LMMS pendrive (references/libcdj/rekordbox, no audio): the library the captured server_stream.bin was served from.\n')
import hashlib
for tree in (out, out7):
    sums = []
    for dirpath, _dirs, files in sorted(os.walk(tree)):
        for fn in sorted(files):
            if fn == 'SHA256SUMS':
                continue
            full = os.path.join(dirpath, fn)
            sums.append('%s  ./%s' % (hashlib.sha256(open(full, 'rb').read()).hexdigest(), os.path.relpath(full, tree)))
    open(os.path.join(tree, 'SHA256SUMS'), 'w').write('\n'.join(sorted(sums, key=lambda l: l.split('  ')[1])) + '\n')
    print('built', tree)
